"""Interval merging: overlaps and touching endpoints."""


def merge_intervals(intervals):
    """Merge integer [start, end] pairs.

    Overlapping and touching (end == start of next) intervals merge.
    Output sorted by start. Input not mutated. Reversed pairs (start > end)
    raise ValueError.
    """
    normalized = []
    for pair in intervals:
        try:
            start, end = pair
        except (TypeError, ValueError):
            raise ValueError(f"interval must be a pair: {pair!r}")
        if start > end:
            raise ValueError(f"reversed interval: {pair!r}")
        normalized.append((start, end))

    normalized.sort()

    merged = []
    for start, end in normalized:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))
    return merged

