import unittest

from solution import merge_intervals


class TestMergeIntervals(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_single(self):
        self.assertEqual(merge_intervals([(1, 3)]), [(1, 3)])

    def test_overlap(self):
        self.assertEqual(merge_intervals([(1, 4), (2, 6)]), [(1, 6)])

    def test_touching_endpoints(self):
        self.assertEqual(merge_intervals([(1, 3), (3, 5)]), [(1, 5)])
        self.assertEqual(merge_intervals([(1, 2), (2, 4)]), [(1, 4)])
        self.assertEqual(
            merge_intervals([(5, 6), (6, 7), (1, 3)]), [(1, 3), (5, 7)]
        )

    def test_adjacent_but_not_touching(self):
        # endpoints 2 and 3 differ: no shared endpoint, stays separate
        self.assertEqual(merge_intervals([(1, 2), (3, 4)]), [(1, 2), (3, 4)])

    def test_disjoint_stays_separate(self):
        self.assertEqual(merge_intervals([(1, 2), (4, 5)]), [(1, 2), (4, 5)])

    def test_sorted_output(self):
        self.assertEqual(merge_intervals([(5, 6), (1, 2)]), [(1, 2), (5, 6)])

    def test_unsorted_input(self):
        self.assertEqual(
            merge_intervals([(10, 12), (1, 3), (2, 4), (12, 13)]),
            [(1, 4), (10, 13)],
        )

    def test_contained_interval(self):
        self.assertEqual(merge_intervals([(1, 10), (3, 4)]), [(1, 10)])

    def test_chain(self):
        self.assertEqual(
            merge_intervals([(1, 2), (2, 3), (3, 4)]), [(1, 4)]
        )

    def test_duplicates(self):
        self.assertEqual(merge_intervals([(1, 1), (1, 1)]), [(1, 1)])

    def test_negative(self):
        self.assertEqual(merge_intervals([(-5, -1), (-2, 3)]), [(-5, 3)])

    def test_no_mutation(self):
        data = [(5, 6), (1, 2), (2, 4)]
        snapshot = list(data)
        merge_intervals(data)
        self.assertEqual(data, snapshot)

    def test_no_mutation_inner_tuples(self):
        a = (1, 4)
        b = (2, 6)
        data = [a, b]
        merge_intervals(data)
        self.assertEqual(data, [a, b])

    def test_reversed_raises(self):
        with self.assertRaises(ValueError):
            merge_intervals([(5, 1)])

    def test_reversed_raises_even_unsorted(self):
        with self.assertRaises(ValueError):
            merge_intervals([(1, 2), (9, 3)])

    def test_reversed_rejected_before_merge(self):
        with self.assertRaises(ValueError):
            merge_intervals([(1, 10), (6, 2)])


if __name__ == "__main__":
    unittest.main()
